module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic in,
    output logic out
);

    typedef enum logic {
        A = 1'b0,
        B = 1'b1
    } state_t;

    state_t current_state, next_state;

    // Sequential state register
    always_ff @(posedge clk) begin
        if (reset) begin
            current_state <= B;
        end else begin
            current_state <= next_state;
        end
    end

    // Combinational next state and output logic
    always_comb begin
        next_state = current_state;
        out = 1'b0;

        case (current_state)
            B: begin
                out = 1'b1;
                if (in == 1'b0) begin
                    next_state = A;
                end else begin
                    next_state = B;
                end
            end
            A: begin
                out = 1'b0;
                if (in == 1'b0) begin
                    next_state = B;
                end else begin
                    next_state = A;
                end
            end
            default: begin
                next_state = B;
                out = 1'b1;
            end
        endcase
    end

endmodule

