module tb_TopModule;
    logic clk;
    logic reset;
    logic in;
    logic out;

    TopModule dut (
        .clk(clk),
        .reset(reset),
        .in(in),
        .out(out)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        reset = 1;
        in = 0;
        #12;
        // Check reset state: B (out = 1)
        if (out !== 1'b1) begin
            $display("SELFFAIL: Reset state output incorrect, got %b, expected 1", out);
            $finish;
        end

        // Release reset
        reset = 0;
        #10;

        // In state B (out=1), in=0 -> should go to A (out=0)
        in = 0;
        #10;
        if (out !== 1'b0) begin
            $display("SELFFAIL: Transition B->A failed, got %b, expected 0", out);
            $finish;
        end

        // In state A (out=0), in=1 -> should stay A (out=0)
        in = 1;
        #10;
        if (out !== 1'b0) begin
            $display("SELFFAIL: Transition A->A failed, got %b, expected 0", out);
            $finish;
        end

        // In state A (out=0), in=0 -> should go to B (out=1)
        in = 0;
        #10;
        if (out !== 1'b1) begin
            $display("SELFFAIL: Transition A->B failed, got %b, expected 1", out);
            $finish;
        end

        // In state B (out=1), in=1 -> should stay B (out=1)
        in = 1;
        #10;
        if (out !== 1'b1) begin
            $display("SELFFAIL: Transition B->B failed, got %b, expected 1", out);
            $finish;
        end

        // Test synchronous reset while running
        reset = 1;
        #10;
        if (out !== 1'b1) begin
            $display("SELFFAIL: Synchronous reset failed, got %b, expected 1", out);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

module tb_TopModule;
