        // Release reset
        @(negedge clk);
        reset = 0;

        // State B, in=0 -> should go to A on next posedge
        in = 0;
        @(posedge clk);
        #1; // small delay after posedge
        if (out !== 1'b0) begin
            $display("SELFFAIL: Transition B->A failed, got %b, expected 0", out);
            $finish;
        end

        // State A, in=1 -> should stay A
        @(negedge clk);
        in = 1;
        @(posedge clk);
        #1;
        if (out !== 1'b0) begin
            $display("SELFFAIL: Transition A->A failed, got %b, expected 0", out);
            $finish;
        end

        // State A, in=0 -> should go to B
        @(negedge clk);
        in = 0;
        @(posedge clk);
        #1;
        if (out !== 1'b1) begin
            $display("SELFFAIL: Transition A->B failed, got %b, expected 1", out);
            $finish;
        end

        // State B, in=1 -> should stay B
        @(negedge clk);
        in = 1;
        @(posedge clk);
        #1;
        if (out !== 1'b1) begin
            $display("SELFFAIL: Transition B->B failed, got %b, expected 1", out);
            $finish;
        end

        // Test synchronous reset while running
        @(negedge clk);
        reset = 1;
        @(posedge clk);
        #1;
        if (out !== 1'b1) begin
            $display("SELFFAIL: Synchronous reset failed, got %b, expected 1", out);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
